/* cppi::91190e0d3ec772246606e78eceac5625b82bf59661ab2447ca08e27a49ab8948 */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-05' and business_date <= date '2025-06-05' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
